'use strict';
// "How I Got This Car": the stickman tells how he went from broke to a
// millionaire. Timing comes from voice.js (generated by voice.py), so scenes
// stay locked to the narration.

const V = window.VOICE;
const L = V.lines;
window.DURATION = V.duration;
const ls = (i) => L[i].s, le = (i) => L[i].e;
const wt = (i, w, which) => wordTime(L, i, w, which);
const CHUNKS = buildChunks(L);
// mouth openness when the stickman is speaking on screen
function talk(t) {
  if (!L.some((l) => l.speaker === 'on' && t >= l.s - 0.05 && t <= l.e + 0.05)) return 0;
  return clamp(V.mouth[Math.min(V.mouth.length - 1, Math.floor(t * V.fps))] || 0);
}

// scene boundaries, all derived from the narration
const CUT = {
  rewindA: le(1) + 0.12, rewindB: ls(2) - 0.12,
  brk: ls(6) - 0.25, couch: ls(7) - 0.2, study: ls(10) - 0.22, win: ls(13) - 0.25,
  meet: ls(16) - 0.25, million: ls(18) - 0.25, car2: ls(20) - 0.25,
};

// ---------- night drive ----------
function buildings(seed, n, w0, w1, h0, h1) {
  const r = rng(seed); const out = []; let x = 0;
  for (let i = 0; i < n; i++) {
    const w = w0 + r() * (w1 - w0), h = h0 + r() * (h1 - h0), wins = [];
    for (let yy = 18; yy < h - 20; yy += 26) for (let xx = 12; xx < w - 14; xx += 20) if (r() < 0.32) wins.push([xx, yy]);
    out.push({ x, w, h, wins }); x += w + 6 + r() * 20;
  }
  return { list: out, w: x };
}
const FAR = buildings(3, 14, 60, 130, 140, 330), NEAR = buildings(8, 12, 80, 160, 200, 430);
const STARS = (() => { const r = rng(12); return Array.from({ length: 40 }, () => [r() * 720, 280 + r() * 420, r() * 6, 0.8 + r() * 1.6]); })();
const ROAD = 1020, CAR = { x: 370, y: 1054 };

function driveBG(t, d) {
  let o = `<rect width="720" height="1280" fill="url(#sky)"/>`;
  for (const [x, y, ph, r] of STARS) o += `<circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r)}" fill="#fff" opacity="${(0.3 + 0.3 * Math.sin(t * 2 + ph)).toFixed(2)}"/>`;
  o += `<circle cx="590" cy="380" r="40" fill="#f3efe4" filter="url(#glow)"/><circle cx="578" cy="370" r="7" fill="#dcd6c8"/><circle cx="602" cy="395" r="5" fill="#dcd6c8"/>`;
  const layer = (B, k, fill, stroke, wins) => {
    let s = '';
    const off = (d * k) % B.w;
    for (const rep of [0, 1]) {
      for (const b of B.list) {
        const x = b.x - off + rep * B.w - 40;
        if (x > 760 || x + b.w < -40) continue;
        s += `<rect x="${f1(x)}" y="${f1(ROAD - b.h)}" width="${f1(b.w)}" height="${f1(b.h)}" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;
        if (wins) for (const [wx, wy] of b.wins) s += `<rect x="${f1(x + wx)}" y="${f1(ROAD - b.h + wy)}" width="8" height="12" fill="${GOLD}" opacity="0.55"/>`;
      }
    }
    return s;
  };
  o += layer(FAR, 0.04, '#0a0a10', '#191922', false) + layer(NEAR, 0.12, '#0e0e0e', '#2a2a2a', true);
  // street lamps
  const sp = 560, offL = (d * 0.7) % sp;
  for (let i = 0; i < 3; i++) {
    const x = i * sp - offL + 120;
    o += `<polygon points="${f1(x + 40)},${ROAD - 290} ${f1(x - 30)},${ROAD + 60} ${f1(x + 150)},${ROAD + 60}" fill="url(#lampcone)"/>`;
    o += `<path d="M ${f1(x)} ${ROAD + 10} V ${ROAD - 300} Q ${f1(x)} ${ROAD - 320} ${f1(x + 20)} ${ROAD - 320} H ${f1(x + 48)}" fill="none" stroke="#666" stroke-width="7" stroke-linecap="round"/>`;
    o += `<rect x="${f1(x + 26)}" y="${ROAD - 322}" width="34" height="12" rx="4" fill="#fff6d0" filter="url(#glow)"/>`;
  }
  o += `<rect x="0" y="${ROAD}" width="720" height="${1280 - ROAD}" fill="#0b0b0b"/><line x1="0" y1="${ROAD}" x2="720" y2="${ROAD}" stroke="#3a3a3a" stroke-width="3"/>`;
  const offD = d % 160;
  for (let j = 0; j < 7; j++) o += `<rect x="${f1(j * 160 - offD - 40)}" y="1188" width="80" height="9" rx="4" fill="#4a4a4a"/>`;
  o += `<line x1="0" y1="1262" x2="720" y2="1262" stroke="#2a2a2a" stroke-width="4"/>`;
  return o;
}
function speedLines(t, k = 1) {
  const r = rng(77); let o = '';
  for (let i = 0; i < 14; i++) {
    const y = 760 + r() * 360, len = 60 + r() * 140, v = 1300 + r() * 900, ph = r() * 1000;
    const x = 760 - ((t * v * k + ph) % 1000);
    o += `<line x1="${f1(x)}" y1="${f1(y)}" x2="${f1(x + len)}" y2="${f1(y)}" stroke="#fff" stroke-width="2" opacity="${(0.12 * k).toFixed(3)}" stroke-linecap="round"/>`;
  }
  return o;
}
// car facing right; returns layers so the driver can sit inside
function carParts(t, d, cx, cy) {
  const G = (b) => `<g transform="translate(${f1(cx)} ${f1(cy)})">${b}</g>`;
  const back = G(`<path d="M -150 -60 L -140 -168 Q -138 -182 -122 -180 L -104 -176 Q -92 -172 -94 -160 L -100 -60 Z" fill="#141414" stroke="${WHITE}" stroke-width="4" stroke-linejoin="round"/>`);
  let body = `<polygon points="272,-30 640,-140 640,90" fill="url(#beam)"/>`;
  body += `<path d="M -268 8 L -276 -40 Q -274 -64 -246 -70 L -96 -78 L -92 -60 L 80 -60 L 84 -68 Q 180 -60 262 -40 Q 280 -32 276 -14 L 272 8 L 232 8 A 62 62 0 0 0 108 8 L -108 8 A 62 62 0 0 0 -232 8 Z" fill="#0f0f0f" stroke="${WHITE}" stroke-width="5" stroke-linejoin="round"/>`;
  body += `<path d="M -250 -34 L 250 -26" stroke="${GOLD}" stroke-width="5" stroke-linecap="round" filter="url(#glow2)"/>`;
  body += `<path d="M -18 -58 L -24 2" stroke="#444" stroke-width="3"/><path d="M -90 -40 L -44 -40" stroke="#555" stroke-width="5" stroke-linecap="round"/>`;
  body += `<path d="M 84 -64 L 128 -122 L 138 -120 L 98 -62 Z" fill="rgba(160,210,255,0.18)" stroke="${WHITE}" stroke-width="3" stroke-linejoin="round"/>`;
  body += `<path d="M 246 -42 L 270 -36 L 268 -26 L 244 -30 Z" fill="#fffbe0" filter="url(#glow)"/>`;
  body += `<path d="M -276 -46 L -266 -48 L -266 -34 L -276 -32 Z" fill="${RED}" filter="url(#glow)"/>`;
  const rot = ((d / 46) * 180) / Math.PI;
  for (const wx of [-170, 170]) {
    body += `<g transform="translate(${wx} 0)"><circle r="46" fill="#080808" stroke="${WHITE}" stroke-width="4"/><circle r="29" fill="#151515" stroke="#bdbdbd" stroke-width="3"/>`;
    body += `<g transform="rotate(${f1(rot % 360)})">` + [0, 72, 144, 216, 288].map((a) => `<line x1="0" y1="0" x2="${f1(27 * Math.cos((a * Math.PI) / 180))}" y2="${f1(27 * Math.sin((a * Math.PI) / 180))}" stroke="#bdbdbd" stroke-width="4"/>`).join('') + '</g>';
    body += `<circle r="7" fill="${GOLD}"/></g>`;
  }
  body = G(body);
  const wheel = G(`<line x1="62" y1="-64" x2="44" y2="-90" stroke="#777" stroke-width="5"/><ellipse cx="40" cy="-96" rx="9" ry="27" transform="rotate(-18 40 -96)" fill="none" stroke="${WHITE}" stroke-width="5"/>`);
  return { back, body, wheel };
}

// camera: maps focus point F to screen point P at zoom z
function cam(F, P, z, body) {
  const tx = P[0] - z * F[0], ty = P[1] - z * F[1];
  return `<g transform="translate(${f1(tx)} ${f1(ty)}) scale(${z.toFixed(4)})">${body}</g>`;
}

function driveScene(t, o2) {
  const { d, carX, face, shades, shadesDrop, hN, hF, tilt, zoom, focusP, lines } = o2;
  const cx = carX, cy = CAR.y + Math.sin(t * 13) * 1.6;
  const car = carParts(t, d, cx, cy);
  const hip = [cx - 35, cy - 46];
  const sm = stick({ x: hip[0], y: hip[1], s: 0.95, lean: 4, tilt, hN, hF, fN: [0, 0], fF: [0, 0], hideLegs: true, face, blink: blink(t, 0.5), talk: talk(t), shades, shadesDrop, chain: 'gold' });
  let o = driveBG(t, d) + car.back + sm.back + car.body + car.wheel + sm.front + speedLines(t, lines ?? 1);
  return { svg: cam([360, 820], focusP, zoom, o), head: sm.head, hip };
}

// ---------- scene: opening drive ----------
function sceneCar1(t) {
  const d = t * 760;
  const cx = CAR.x, cy = CAR.y;
  const wheelN = [cx + 46, cy - 120], wheelF = [cx + 30, cy - 104];
  const gest = Math.max(bump(t, wt(0, 'this') - 0.15, le(0) + 0.35), 0);
  const hN = mix(wheelN, [cx + 150, cy - 210], gest);
  const z = track(t, [[0, 1], [0.5, 1], [2.6, 1.42], [CUT.rewindA, 1.55]]);
  const P = mix([360, 820], [360, 840], prog(z, 1, 1.42));
  const drop = track(t, [[0, 0], [wt(1, 'year') - 0.1, 0], [wt(1, 'year') + 0.25, 1]]);
  const face = faces(t, [[0, 'smirk'], [ls(1), 'serious'], [wt(1, 'broke'), 'sad']]);
  const tilt = -4 + Math.sin(t * 2.2) * 2 + (t > wt(1, 'broke') ? 10 * prog(t, wt(1, 'broke'), wt(1, 'broke') + 0.4) : 0);
  return driveScene(t, { d, carX: cx, face, shades: 1, shadesDrop: drop, hN, hF: wheelF, tilt, zoom: z, focusP: P }).svg;
}

// VHS rewind into the flashback
function rewind(t) {
  const u = prog(t, CUT.rewindA, CUT.rewindB);
  const back = CUT.rewindA - u * 5.5;
  let o = sceneCar1(Math.max(0, back));
  const r = rng(Math.floor(t * 30));
  for (let i = 0; i < 9; i++) {
    const y = r() * 1280, h = 3 + r() * 16;
    o += `<rect x="0" y="${f1(y)}" width="720" height="${f1(h)}" fill="#fff" opacity="${(0.08 + r() * 0.25).toFixed(2)}"/>`;
  }
  o += `<rect width="720" height="1280" fill="url(#scan)"/><rect width="720" height="1280" fill="#000" opacity="${(0.25 + 0.5 * u).toFixed(2)}"/>`;
  o += vhsTag(t, 1);
  return o;
}
function vhsTag(t, op) {
  return `<g opacity="${op.toFixed(3)}">${text(360, 640, '◀◀', { size: 90, fill: WHITE, family: 'Anton', weight: 400, filter: 'glow' })}${text(360, 730, '1 YEAR AGO', { size: 64, fill: GOLD, family: 'Oswald', filter: 'glow' })}</g>`;
}

// ---------- scene: losing every day ----------
const BOX = { x0: 70, x1: 640, y0: 330, y1: 720 };
const LOSE_CLOSES = [100, 103, 99, 104, 101, 98, 102, 97, 100, 96, 99, 95, 98, 94, 97, 95, 98,
  102, 107, 111, 116, 120, 119, 113, 106, 100, 98, 104, 109, 113, 111, 112, 56, 51, 53];
const CL = candlesFrom(LOSE_CLOSES, 5, 3);
const S1 = { hip: [200, 1070], s: 1.15, chairX: 226, BUY: [352, 900], SELL: [460, 900], floor: 1190 };

function presser(t, presses) {
  let b = 0, s = 0;
  for (const [pt, w] of presses) {
    const v = t >= pt && t < pt + 0.35 ? 1 - prog(t, pt + 0.1, pt + 0.35) : 0;
    if (w === 'BUY') b = Math.max(b, v); else s = Math.max(s, v);
  }
  return [b, s];
}
function pressHand(t, presses, rest, extra = []) {
  const k = [[CUT.rewindB, rest]];
  for (const [pt, w] of presses) {
    const tgt = w === 'BUY' ? S1.BUY : S1.SELL;
    k.push([pt - 0.16, [tgt[0] - 62, tgt[1] - 30]], [pt, [tgt[0] - 36, tgt[1] + 4]], [pt + 0.12, [tgt[0] - 44, tgt[1] - 10]]);
  }
  return track(t, k.concat(extra).sort((a, b) => a[0] - b[0]));
}

function sceneLose(t) {
  let o = '';
  const tTops = wt(4, 'tops'), tSold = wt(4, 'sold'), tBottoms = wt(4, 'bottoms');
  const tBlew = wt(5, 'blew'), tAcc = wt(5, 'account');
  const shake = t > tBlew && t < tBlew + 0.6 ? (1 - prog(t, tBlew, tBlew + 0.6)) * 13 : 0;
  o += `<g transform="translate(${f1(Math.sin(t * 91) * shake)} ${f1(Math.cos(t * 77) * shake)})">`;
  const nv = track(t, [[CUT.rewindB, 8], [ls(4), 16], [tTops + 0.05, 22], [tSold, 25], [tBottoms + 0.1, 26], [ls(5), 29], [tBlew - 0.05, 31], [tBlew + 0.4, 32], [le(5) + 0.8, 34]], ease.lin);
  const ch = chartSVG(CL, nv, BOX, { minSpan: 30 });
  o += ch.svg;
  // trade markers
  const marker = (i, price, label, col, below, t0) => {
    if (t < t0 || nv < i + 0.5) return '';
    const p = ease.back(prog(t, t0, t0 + 0.3)), x = ch.X(i), y = ch.Y(price) + (below ? 30 : -30);
    return `<g transform="translate(${f1(x)} ${f1(y)}) scale(${p.toFixed(3)})"><rect x="-38" y="-17" width="76" height="34" rx="8" fill="${col}" filter="url(#glow2)"/>${text(0, 9, label, { size: 22, fill: '#0a0a0a' })}<path d="M -8 ${below ? -17 : 17} L 0 ${below ? -27 : 27} L 8 ${below ? -17 : 17} Z" fill="${col}"/></g>`;
  };
  o += marker(21, 121.5, 'BUY', GREEN, false, tTops) + marker(25, 95.5, 'SELL', RED, true, tBottoms);
  // presses
  const lw = lineWords(L[2]);
  const presses = lw.map((w, i) => [w.s, i % 2 ? 'SELL' : 'BUY']).concat(lineWords(L[3]).filter((_, i) => i % 2 === 0).map((w, i) => [w.s + 0.1, i % 2 ? 'BUY' : 'SELL']), [[tTops, 'BUY'], [tBottoms, 'SELL']]);
  const [pb, ps] = presser(t, presses);
  o += button(S1.BUY[0], S1.BUY[1], 'BUY', pb, GREEN) + button(S1.SELL[0], S1.SELL[1], 'SELL', ps, RED);
  // balance
  const steps = lineWords(L[3]).map((w) => w.s);
  const balKeys = [[CUT.rewindB, 10000], [ls(3), 9900]];
  steps.forEach((s, i) => balKeys.push([s, 9900 - i * 650], [s + 0.18, 9900 - (i + 1) * 650]));
  balKeys.push([tTops, 7300], [tSold, 5900], [tBottoms + 0.3, 4800], [tBlew, 4800], [tAcc + 0.2, 0]);
  const bal = track(t, balKeys.sort((a, b) => a[0] - b[0]));
  const balCol = t < ls(3) ? WHITE : RED;
  o += text(640, 1010, 'BALANCE', { size: 22, fill: GREY, anchor: 'end', weight: 500, ls: 2 });
  o += text(640, 1066, money(bal), { size: 54, fill: balCol, anchor: 'end', filter: 'glow2' });
  steps.forEach((s) => {
    if (t > s && t < s + 0.9) {
      const u = prog(t, s, s + 0.9);
      o += text(600, 990 - u * 70, '-$650', { size: 30, fill: RED, op: (1 - u).toFixed(2), anchor: 'end' });
    }
  });
  if (t > tBlew && t < tBlew + 0.9) o += `<rect x="-20" y="-20" width="760" height="1320" fill="${RED}" opacity="${(0.3 * (1 - prog(t, tBlew, tBlew + 0.9))).toFixed(3)}"/>`;

  // stickman
  const hip = S1.hip;
  const rest = [300, 930];
  const hN = pressHand(t, presses, rest, [[tBlew - 0.05, [300, 905]], [tBlew + 0.2, [300, 820]], [tAcc, [300, 830]], [tAcc + 0.7, [306, 1072]]]);
  const hF = track(t, [[CUT.rewindB, [262, 945]], [tBlew, [262, 945]], [tBlew + 0.2, [250, 840]], [tAcc, [250, 850]], [tAcc + 0.7, [292, 1080]]]);
  const body = track(t, [[CUT.rewindB, { lean: 12, tilt: -4 }], [tBlew, { lean: 14, tilt: -4 }], [tBlew + 0.2, { lean: -6, tilt: -12 }], [tAcc, { lean: -4, tilt: -8 }], [tAcc + 0.8, { lean: 34, tilt: 26 }]]);
  const frantic = t < tBlew ? Math.sin(t * 22) * 1.5 : 0;
  const face = faces(t, [[CUT.rewindB, 'focus'], [ls(3), 'worried'], [ls(4), 'angry'], [tBottoms, 'shocked'], [ls(5), 'worried'], [tBlew, 'shocked'], [tAcc + 0.2, 'sad']]);
  const sm = stick({ x: hip[0], y: hip[1], s: S1.s, lean: body.lean + frantic, tilt: body.tilt, hN, hF, ...sitFeet(hip, S1.s), face, blink: blink(t) });
  o += chair(S1.chairX, hip[1] + 13, S1.floor) + sm.svg;

  // ACCOUNT BLOWN stamp
  if (t > tAcc) {
    const p = prog(t, tAcc, tAcc + 0.22), sc = lerp(2.2, 1, ease.out(p));
    o += `<g transform="translate(360 560) rotate(-8) scale(${sc.toFixed(3)})" opacity="${p.toFixed(3)}"><rect x="-250" y="-62" width="500" height="124" rx="12" fill="rgba(0,0,0,0.6)" stroke="${RED}" stroke-width="8" filter="url(#glow2)"/>${text(0, 26, 'ACCOUNT BLOWN', { size: 70, fill: RED, family: 'Anton', weight: 400 })}</g>`;
  }
  o += '</g>';
  // "1 YEAR AGO" tag fades out at the start of the flashback
  if (t < CUT.rewindB + 1.0) o += vhsTag(t, 1 - prog(t, CUT.rewindB + 0.4, CUT.rewindB + 1.0));
  return o;
}

// ---------- scene: the break ----------
function noIcon(x, y, kind, p) {
  if (p <= 0) return '';
  let o = `<g transform="translate(${x} ${y}) scale(${ease.back(p).toFixed(3)})"><rect x="-110" y="-90" width="220" height="180" rx="24" fill="#0c0c0c" stroke="#333" stroke-width="3"/>`;
  if (kind === 'chart') {
    [[-60, 20, -10, GREEN], [-25, -10, 30, RED], [10, -30, 10, GREEN], [45, -50, -20, GREEN]].forEach(([cx, a, b, c]) => {
      o += `<line x1="${cx}" y1="${a - 15}" x2="${cx}" y2="${b + 15}" stroke="${c}" stroke-width="3"/><rect x="${cx - 9}" y="${Math.min(a, b)}" width="18" height="${Math.abs(a - b) + 4}" fill="${c}"/>`;
    });
  } else {
    o += `<rect x="-56" y="-26" width="112" height="52" rx="11" fill="#050505" stroke="${WHITE}" stroke-width="3"/>` + text(0, 11, 'BUY', { size: 30 });
  }
  o += `<circle r="72" fill="none" stroke="${RED}" stroke-width="10"/><line x1="-51" y1="-51" x2="51" y2="51" stroke="${RED}" stroke-width="10"/></g>`;
  return o;
}
function sceneBreak(t) {
  let o = '';
  const deskY = 958;
  const tStep = wt(6, 'stepped');
  o += desk(330, 700, deskY, 1210);
  const open = 1 - ease.inOut(prog(t, tStep - 0.1, tStep + 0.3));
  o += laptop(432, deskY, 210, 150, (x, y, w, h) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#140808"/><path d="M ${x + 10} ${y + 30} L ${x + 60} ${y + 50} L ${x + 100} ${y + 45} L ${x + 150} ${y + 110} L ${x + w - 10} ${y + 120}" fill="none" stroke="${RED}" stroke-width="5" filter="url(#glow2)"/>`, open);
  o += chair(226, 1083, 1190);
  const up = ease.inOut(prog(t, tStep + 0.2, tStep + 0.7));
  const walk = prog(t, tStep + 0.6, tStep + 1.6);
  const flip = up > 0.5 ? -1 : 1;
  const s = 1.15, sy = standY(1190, s);
  const x = lerp(200, 230, up) - ease.out(walk) * 110;
  const hipY = lerp(1070, sy, up) - Math.abs(Math.sin(walk * Math.PI * 3)) * 5 * (walk > 0 && walk < 1);
  const ph = walk * Math.PI * 3;
  const sf = sitFeet([200, 1070], s);
  const fN = up < 1 ? mix(sf.fN, [x + 22 * flip, 1190], up) : [x + 22 * flip + Math.sin(ph) * 26 * flip, 1190 - Math.max(0, Math.cos(ph)) * 14 * (walk > 0 && walk < 1)];
  const fF = up < 1 ? mix(sf.fF, [x - 10 * flip, 1192], up) : [x - 10 * flip - Math.sin(ph) * 26 * flip, 1192 - Math.max(0, -Math.cos(ph)) * 14 * (walk > 0 && walk < 1)];
  const hN = up < 0.5 ? mix([360, 940], [300, 1000], up * 2) : [x + 26 * flip, sy + 100];
  const hF = up < 0.5 ? [290, 950] : [x - 4 * flip, sy + 104];
  const face = faces(t, [[CUT.brk, 'sad'], [tStep + 0.6, 'bored'], [wt(6, 'trades') + 0.3, 'calm']]);
  const sm = stick({ x, y: hipY, s, flip, lean: up > 0.5 ? 10 - 6 * walk : 12, tilt: 10, hN, hF, fN, fF, face, blink: blink(t, 0.9) });
  o += sm.svg;
  o += noIcon(200, 520, 'chart', prog(t, wt(6, 'charts') - 0.05, wt(6, 'charts') + 0.25));
  o += noIcon(520, 520, 'trade', prog(t, wt(6, 'trades') - 0.05, wt(6, 'trades') + 0.25));
  return o;
}

// ---------- TJR, drawn with his hair, beard and chains ----------
function tjrHead(x, y, sc, face = FACE.happy, t = 0) {
  return `<g transform="translate(${f1(x)} ${f1(y)}) scale(${sc})">${headSVG([0, 0], 0, { hair: true, beard: true, face, blink: blink(t, 2.4) })}</g>`;
}
function tjrTeacher(t, x, floor, s, o2 = {}) {
  const sy = standY(floor, s);
  const pointing = o2.point ?? 1;
  const hN = mix([x + 20, sy + 100 * s], [x + 115 * s, sy - 240 * s + Math.sin(t * 3) * 10 * s], pointing);
  return stick({ x, y: sy, s, flip: o2.flip ?? 1, lean: 2, tilt: -4, hN, hF: [x - 6, sy + 102 * s], fN: [x + 22 * s, floor], fF: [x - 10 * s, floor + 2], face: o2.face || FACE.happy, blink: blink(t, 2.1), hair: true, beard: true, chain: 'silver', talk: o2.talk || 0 }).svg;
}
// a small "whiteboard" chart TJR teaches from
function teachBoard(x, y, w, h, t, ann) {
  let o = `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="#0d0d0d" stroke="#444" stroke-width="3"/>`;
  const closes = [50, 46, 52, 48, 55, 51, 58, 54, 62, 59, 68, 74];
  const cs = candlesFrom(closes, 9, 2);
  const X = (i) => x + 20 + i * ((w - 40) / cs.length) + 8, Y = (v) => y + h - 16 - ((v - 40) / 40) * (h - 32);
  cs.forEach((c, i) => {
    const col = c.c >= c.o ? GREEN : RED;
    o += `<line x1="${f1(X(i))}" y1="${f1(Y(c.h))}" x2="${f1(X(i))}" y2="${f1(Y(c.l))}" stroke="${col}" stroke-width="2"/><rect x="${f1(X(i) - 6)}" y="${f1(Y(Math.max(c.o, c.c)))}" width="12" height="${f1(Math.max(2, Math.abs(Y(c.o) - Y(c.c))))}" fill="${col}"/>`;
  });
  const lines = [['TARGET', 72, GREEN], ['ENTRY', 55, GOLD], ['STOP', 46, RED]];
  lines.forEach(([lab, v, col], i) => {
    const p = ann[i] ?? 0;
    if (p <= 0) return;
    o += `<line x1="${x + 12}" y1="${f1(Y(v))}" x2="${f1(x + 12 + (w - 24) * ease.out(p))}" y2="${f1(Y(v))}" stroke="${col}" stroke-width="3" stroke-dasharray="8 6"/>`;
    o += `<g opacity="${p.toFixed(2)}"><rect x="${x + w - 84}" y="${f1(Y(v) - 24)}" width="72" height="20" rx="4" fill="${col}"/>${text(x + w - 48, Y(v) - 9, lab, { size: 14, fill: '#0a0a0a' })}</g>`;
  });
  return o;
}

